"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[2156],{2156(e,s,n){n.d(s,{content:()=>l,description:()=>r,keywords:()=>a,title:()=>t});n(5043);var i=n(579);const t="Le Livre blanc SEND 2026 et l'enseignement des sciences",r="Le Livre blanc SEND 2026 accorde \xe0 chaque \xe9l\xe8ve en situation de SEND (besoins \xe9ducatifs particuliers) un Individual Support Plan (plan de soutien individualis\xe9) statutaire et fait de l'inclusion une priorit\xe9 d'Ofsted d\xe8s septembre. Voici ce que cela signifie pour l'enseignement des sciences.",a=["Livre blanc SEND 2026","plan de soutien individualis\xe9","travaux pratiques de sciences SEND","cadre d'inclusion Ofsted 2026","laboratoires de sciences accessibles SEND","preuves de progr\xe8s SEND","\xe9ducation scientifique inclusive","laboratoires virtuels SEND"],l=(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)("p",{children:["En f\xe9vrier 2026, le gouvernement a publi\xe9 son Livre blanc sur les \xe9coles, ",(0,i.jsx)("em",{children:"Every Child Achieving and Thriving"}),", exposant la r\xe9forme la plus importante de la prise en charge des besoins \xe9ducatifs particuliers depuis plus d'une d\xe9cennie (",(0,i.jsx)("a",{href:"https://www.gov.uk/government/publications/every-child-achieving-and-thriving",target:"_blank",rel:"noopener noreferrer",children:"DfE, 2026"}),"). En son c\u0153ur se trouve un engagement simple mais d'une grande port\xe9e : chaque enfant identifi\xe9 comme en situation de SEND (besoins \xe9ducatifs particuliers) dans une \xe9cole ordinaire devrait disposer d'un Individual Support Plan (plan de soutien individualis\xe9) statutaire, et les EHCP (plans d'\xe9ducation, de sant\xe9 et de soins) devraient \xeatre r\xe9serv\xe9s \xe0 ceux dont les besoins sont les plus complexes."]}),(0,i.jsx)("p",{children:"Pour les d\xe9partements de sciences, ce n'est pas une simple note administrative. Cela modifie qui est responsable de la mise en \u0153uvre et, tout aussi important, de la d\xe9monstration par les preuves d'un soutien de grande qualit\xe9, et cela dans la mati\xe8re o\xf9 l'inclusion est la plus difficile \xe0 atteindre. La science pratique repose sur du mat\xe9riel, des dangers et une technique physique. C'est la partie du programme o\xf9 les \xe9l\xe8ves ayant des besoins suppl\xe9mentaires se retrouvent le plus souvent \xe0 regarder plut\xf4t qu'\xe0 faire. Le Livre blanc demande \xe0 chaque \xe9cole de combler cet \xe9cart, et d'\xeatre en mesure de prouver qu'elle l'a fait."}),(0,i.jsx)("h2",{children:"Qu'a r\xe9ellement chang\xe9 le Livre blanc SEND ?"}),(0,i.jsxs)("p",{children:["La r\xe9forme redessine le lieu o\xf9 le soutien est dispens\xe9. Selon la synth\xe8se du Livre blanc r\xe9alis\xe9e par la House of Commons Library, les EHCP (plans d'\xe9ducation, de sant\xe9 et de soins) doivent \xeatre r\xe9serv\xe9s au cours des prochaines ann\xe9es aux enfants ayant les besoins les plus complexes, tandis que chaque autre \xe9l\xe8ve identifi\xe9 comme en situation de SEND re\xe7oit un Individual Support Plan (plan de soutien individualis\xe9) num\xe9rique et statutaire, d\xe9tenu par son \xe9cole ordinaire. Ces changements sont soutenus par un Inclusive Mainstream Fund (fonds pour l'inclusion en milieu ordinaire) de 1,6 milliard de livres et un service \xab\xa0Experts at Hand\xa0\xbb (experts \xe0 port\xe9e de main) de 1,8 milliard de livres, con\xe7u pour apporter des conseils sp\xe9cialis\xe9s dans les salles de classe ordinaires (",(0,i.jsx)("a",{href:"https://commonslibrary.parliament.uk/research-briefings/cbp-10550/",target:"_blank",rel:"noopener noreferrer",children:"House of Commons Library, 2026"}),")."]}),(0,i.jsx)("p",{children:"Le fil conducteur est clair. Les classes ordinaires, et non les \xe9tablissements sp\xe9cialis\xe9s, deviennent le lieu o\xf9 la majeure partie du soutien SEND est dispens\xe9e et document\xe9e. Cela transf\xe8re une responsabilit\xe9 importante sur les enseignants de mati\xe8re, qui sont d\xe9sormais cens\xe9s non seulement rendre leurs cours accessibles, mais aussi consigner comment ils l'ont fait et quelle diff\xe9rence cela a produit."}),(0,i.jsx)("h2",{children:"Pourquoi la science pratique est-elle si difficile \xe0 rendre inclusive ?"}),(0,i.jsx)("p",{children:"Chaque mati\xe8re fait face \xe0 des d\xe9fis d'inclusion, mais la science pratique en porte un ensemble particulier. Un laboratoire standard regorge de paillasses \xe0 hauteur fixe, de flammes nues, de plaques chauffantes, de verrerie, de scalpels et de r\xe9actifs, utilis\xe9s sous la pression du temps dans une salle bruyante et anim\xe9e. Un \xe9l\xe8ve en fauteuil roulant, un \xe9l\xe8ve souffrant de tremblements des mains, un \xe9l\xe8ve dont l'anxi\xe9t\xe9 monte autour du feu, ou un \xe9l\xe8ve submerg\xe9 par la charge sensorielle peuvent tous se retrouver exclus de l'activit\xe9 m\xeame qui d\xe9finit la mati\xe8re. L'ajustement habituel consiste \xe0 les laisser observer pendant qu'un camarade ou l'enseignant r\xe9alise l'exp\xe9rience, ce qui les \xe9carte discr\xe8tement de l'apprentissage."}),(0,i.jsxs)("p",{children:["Cela vient s'ajouter \xe0 un d\xe9clin plus large des sciences pratiques. Le Science Education Tracker de la Royal Society et d'EngineeringUK a constat\xe9 que les travaux pratiques r\xe9guliers pour les \xe9l\xe8ves de GCSE (examen de fin de scolarit\xe9 obligatoire) sont pass\xe9s de 44% en 2016 \xe0 26% en 2023, les d\xe9monstrations vid\xe9o rempla\xe7ant de plus en plus les exp\xe9riences que les \xe9l\xe8ves r\xe9alisaient autrefois eux-m\xeames (",(0,i.jsx)("a",{href:"https://royalsociety.org/news/2024/04/science-education-tracker-2023/",target:"_blank",rel:"noopener noreferrer",children:"Royal Society, 2024"}),"). Quand les d\xe9monstrations remplacent la pratique, les \xe9l\xe8ves qui perdent le plus sont ceux qui \xe9taient d\xe9j\xe0 les moins en mesure de participer. Une r\xe9forme qui promet un acc\xe8s v\xe9ritable \xe0 chaque \xe9l\xe8ve va directement \xe0 l'encontre de cette tendance."]}),(0,i.jsx)("h2",{children:"Que doit d\xe9montrer un Individual Support Plan ?"}),(0,i.jsx)("p",{children:"Un Individual Support Plan (plan de soutien individualis\xe9) n'est pas un exercice de pure forme. Il est cens\xe9 exposer les obstacles auxquels un \xe9l\xe8ve est confront\xe9, les dispositions et les ajustements mis en place, les r\xe9sultats que ces ajustements visent \xe0 atteindre, ainsi qu'un examen r\xe9gulier de leur efficacit\xe9. Pour un enseignant de sciences, cela signifie pouvoir r\xe9pondre, \xe9l\xe8ve par \xe9l\xe8ve, \xe0 trois questions concr\xe8tes : comment cet enfant a-t-il particip\xe9 \xe0 ce travail pratique, quel ajustement l'a rendu possible, et quels progr\xe8s a-t-il r\xe9alis\xe9s en cons\xe9quence."}),(0,i.jsx)("p",{children:"Ces questions sont difficiles \xe0 aborder honn\xeatement lorsque la participation d'un \xe9l\xe8ve \xe0 un travail pratique se limitait \xe0 regarder depuis le c\xf4t\xe9. Les bonnes intentions et la m\xe9moire ne suffisent plus. Le plan attend un enregistrement, et cet enregistrement doit attester d'une participation et de progr\xe8s, et non d'une simple pr\xe9sence dans la salle."}),(0,i.jsx)("h2",{children:"L'inclusion fait d\xe9sormais partie de chaque inspection d'Ofsted"}),(0,i.jsxs)("p",{children:["La reddition de comptes s'est durcie en parall\xe8le. En juin 2026, Ofsted (l'organisme d'inspection des \xe9coles) a confirm\xe9 qu'\xe0 partir de septembre 2026 l'inclusion traverserait chaque inspection plut\xf4t que d'\xeatre trait\xe9e \xe0 part, les inspecteurs examinant dans quelle mesure les \xe9coles incluent les \xe9l\xe8ves en situation de SEND \xe0 travers le programme, comparant les r\xe9sultats \xe0 ceux d'\xe9coles travaillant avec des groupes d'\xe9l\xe8ves similaires, et attendant des cadres dirigeants qu'ils s'approprient directement l'inclusion (",(0,i.jsx)("a",{href:"https://educationinspection.blog.gov.uk/2026/06/12/what-you-need-to-know-about-the-september-2026-updates-to-education-inspections/",target:"_blank",rel:"noopener noreferrer",children:"Ofsted, 2026"}),"). Un d\xe9partement de sciences incapable de d\xe9montrer comment ses \xe9l\xe8ves en situation de SEND acc\xe8dent aux travaux pratiques et y progressent aura du mal \xe0 apporter la preuve de l'inclusion dans l'une des mati\xe8res qui comptent le plus aux yeux des inspecteurs comme des familles."]}),(0,i.jsx)("h2",{children:"Comment des laboratoires virtuels accessibles donnent \xe0 chaque \xe9l\xe8ve une place \xe0 la paillasse"}),(0,i.jsx)("p",{children:"C'est l\xe0 que nous pensons que les laboratoires virtuels changent la donne. Parce que WhimsyLabs ex\xe9cute un v\xe9ritable moteur physique dans le navigateur, sur les Chromebooks que les \xe9coles poss\xe8dent d\xe9j\xe0, les obstacles qui excluent les \xe9l\xe8ves d'une paillasse physique sont tout simplement absents. Il n'y a pas de flamme \xe0 craindre, pas de verrerie \xe0 laisser tomber, et pas de rythme unique que toute la classe doit suivre. Un \xe9l\xe8ve peut r\xe9p\xe9ter un titrage autant de fois qu'il en a besoin, ralentir une r\xe9action pour suivre chaque \xe9tape, ou revenir \xe0 une dissection sans la surcharge sensorielle d'un laboratoire bond\xe9."}),(0,i.jsx)("p",{children:"R\xe9sultat : des \xe9l\xe8ves qui, autrement, regarderaient une d\xe9monstration r\xe9alisent l'exp\xe9rience eux-m\xeames. Ils choisissent le mat\xe9riel, prennent les d\xe9cisions, rencontrent les r\xe9sultats inattendus et apprennent de leurs propres erreurs. Nous avons con\xe7u pour le SEND d\xe8s le d\xe9part plut\xf4t que d'ajouter l'accessibilit\xe9 apr\xe8s coup, de sorte que les laboratoires fonctionnent avec la navigation au clavier et les technologies d'assistance, permettent un rythme ajustable, et \xe9vitent la pression du temps et le risque physique qui repoussent les \xe9l\xe8ves \xe0 besoins suppl\xe9mentaires en marge d'une s\xe9ance pratique. L'acc\xe8s cesse d'\xeatre une exception \xe0 organiser et devient la norme autour de laquelle la plateforme a \xe9t\xe9 construite."}),(0,i.jsx)("h2",{children:"Transformer la charge de la preuve en une r\xe9ussite document\xe9e"}),(0,i.jsx)("p",{children:"La m\xeame conception qui \xe9largit l'acc\xe8s r\xe9pond aussi \xe0 la question des preuves que soul\xe8ve le Livre blanc. Notre \xe9valuation bas\xe9e sur les processus consigne chaque action qu'un \xe9l\xe8ve effectue : le mat\xe9riel qu'il s\xe9lectionne, l'ordre dans lequel il r\xe9alise les \xe9tapes, sa r\xe9action lorsque quelque chose tourne mal, et l'am\xe9lioration de sa technique au fil des s\xe9ances. Pour un SENCo (coordinateur des besoins \xe9ducatifs particuliers) ou un responsable des sciences, cet enregistrement des interactions est exactement la preuve par \xe9l\xe8ve que demande un Individual Support Plan, et exactement le type de donn\xe9es de progr\xe8s que r\xe9compense le mod\xe8le de comparaison \xe0 contexte similaire d'Ofsted."}),(0,i.jsx)("p",{children:"Au lieu de r\xe9diger de m\xe9moire l'examen d'un ISP (plan de soutien individualis\xe9), un enseignant peut s'appuyer sur une trace document\xe9e de ce qu'un \xe9l\xe8ve a r\xe9ellement fait et du chemin qu'il a parcouru au cours d'un trimestre. Un \xe9l\xe8ve qui ne pourrait jamais tenir une pipette en toute s\xe9curit\xe9 \xe0 une paillasse physique peut tout de m\xeame d\xe9montrer qu'il comprend et sait ex\xe9cuter la proc\xe9dure, et cette d\xe9monstration est enregistr\xe9e automatiquement. La charge de conformit\xe9 devient un sous-produit d'un bon enseignement plut\xf4t qu'un exercice de paperasse distinct ajout\xe9 \xe0 la fin."}),(0,i.jsx)("h2",{children:"Ce que les d\xe9partements de sciences peuvent faire avant septembre"}),(0,i.jsx)("p",{children:"Avec la nouvelle priorit\xe9 d'inspection qui arrive en septembre 2026, il existe une fen\xeatre de planification concr\xe8te. Les d\xe9partements peuvent commencer par recenser quels travaux pratiques obligatoires sont actuellement inaccessibles \xe0 certains \xe9l\xe8ves, et \xeatre honn\xeates sur la fr\xe9quence \xe0 laquelle l'observation a remplac\xe9 la participation. L'Inclusive Mainstream Fund (fonds pour l'inclusion en milieu ordinaire) de 1,6 milliard de livres donne aux directions d'\xe9cole une ligne budg\xe9taire sur laquelle des outils accessibles et g\xe9n\xe9rateurs de preuves peuvent l\xe9gitimement s'appuyer, ce qui rend un projet pilote plus facile \xe0 justifier qu'il ne l'aurait \xe9t\xe9 un an plus t\xf4t."}),(0,i.jsx)("p",{children:"\xc0 partir de l\xe0, un petit projet pilote dans un niveau ou une seule science peut \xe9tablir \xe0 la fois l'acc\xe8s et la trace de preuves avant un d\xe9ploiement plus large. Le but n'est pas de remplacer toutes les exp\xe9riences pratiques, qui restent pr\xe9cieuses pour les \xe9l\xe8ves qui peuvent y prendre part, mais de garantir qu'aucun \xe9l\xe8ve ne reste \xe0 regarder, et que le d\xe9partement puisse montrer, plan par plan, comment il l'a inclus. L'inclusion est un devoir au titre du nouveau Livre blanc, mais c'est aussi une occasion d'offrir \xe0 chaque \xe9l\xe8ve de v\xe9ritables sciences pratiques et les progr\xe8s document\xe9s pour le prouver."}),(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)("h2",{children:"Articles connexes"}),(0,i.jsxs)("ul",{children:[(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/blog/virtual-kidney-dissection-send-engagement",children:"Dissection virtuelle d'un rein : comment les laboratoires virtuels stimulent l'engagement SEND"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/blog/premium-science-education-accessible-grants",children:"Rendre l'\xe9ducation scientifique de qualit\xe9 accessible gr\xe2ce aux subventions"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/blog/virtual-biology-lab-dissections-microscopy",children:"Le laboratoire de biologie virtuel : dissections et microscopie sans les obstacles"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/blog/how-to-choose-virtual-lab-software-school",children:"Comment choisir un logiciel de laboratoire virtuel pour votre \xe9cole"})})]})]}),(0,i.jsxs)("div",{className:"references-section",children:[(0,i.jsx)("h3",{children:"R\xe9f\xe9rences"}),(0,i.jsxs)("ul",{className:"references-list",children:[(0,i.jsxs)("li",{children:["Department for Education. (2026). Every Child Achieving and Thriving (Schools White Paper). GOV.UK."," ",(0,i.jsx)("a",{href:"https://www.gov.uk/government/publications/every-child-achieving-and-thriving",target:"_blank",rel:"noopener noreferrer",children:"https://www.gov.uk/government/publications/every-child-achieving-and-thriving"})]},"ref-1"),(0,i.jsxs)("li",{children:["House of Commons Library. (2026). The Schools White Paper 2026: SEND Reform."," ",(0,i.jsx)("a",{href:"https://commonslibrary.parliament.uk/research-briefings/cbp-10550/",target:"_blank",rel:"noopener noreferrer",children:"https://commonslibrary.parliament.uk/research-briefings/cbp-10550/"})]},"ref-2"),(0,i.jsxs)("li",{children:["Ofsted. (2026). What you need to know about the September 2026 updates to education inspections."," ",(0,i.jsx)("a",{href:"https://educationinspection.blog.gov.uk/2026/06/12/what-you-need-to-know-about-the-september-2026-updates-to-education-inspections/",target:"_blank",rel:"noopener noreferrer",children:"https://educationinspection.blog.gov.uk/2026/06/12/what-you-need-to-know-about-the-september-2026-updates-to-education-inspections/"})]},"ref-3"),(0,i.jsxs)("li",{children:["Royal Society & EngineeringUK. (2024). Science Education Tracker 2023."," ",(0,i.jsx)("a",{href:"https://royalsociety.org/news/2024/04/science-education-tracker-2023/",target:"_blank",rel:"noopener noreferrer",children:"https://royalsociety.org/news/2024/04/science-education-tracker-2023/"})]},"ref-4")]})]})]})}}]);
